        use crate::collections::bounded_vec::BoundedVec;

        #[test]
        fn push_and_pop_operations() {
            let mut vec: BoundedVec<u32, 5> = BoundedVec::new();

            assert_eq(vec.len(), 0);

            vec.push(1);
            assert_eq(vec.len(), 1);
            assert_eq(vec.get(0), 1);

            vec.push(2);
            assert_eq(vec.len(), 2);
            assert_eq(vec.get(1), 2);

            let popped = vec.pop();
            assert_eq(popped, 2);
            assert_eq(vec.len(), 1);

            let popped2 = vec.pop();
            assert_eq(popped2, 1);
            assert_eq(vec.len(), 0);
        }

